import 'jest';
import { parseString } from '../../src';

describe('parseString()', () => {
    test('will error if value is null', () => {
        expect(() => parseString(null)).toThrow();
    });

    test('will error if value is undefined', () => {
        expect(() => parseString(void 0)).toThrow();
    });

    test('will parse valid string values values', () => {
        const testString = 'Some kind of test string';
        expect(parseString(testString)).toEqual(testString);
    });
});